	('d787243e-1169-4351-9840-44027d9f32c7', '2025-10-29 17:18:06.660935+00', '2025-11-05 13:00:16.190808+00', '1ebc41b2-ea7a-4b52-8578-f41a659da782', 'building_type', 'dropdown', NULL, NULL, '["Szabadon álló családi ház", "Oldalhatáron álló családi ház", "Zártsorú családi ház", "Ikerház", "Sorház"]', false, false, NULL, NULL, NULL, NULL, NULL, NULL, '{"en": "Property Type", "hu": "Ingatlan típusa"}', NULL, NULL, '{"en": "Detached family house: accessible within own plot, side yard typically min. 3.0 m\\nSide boundary family house: built on one plot boundary (or max 1.0 m from it), one facade only accessible from neighbor''s plot\\nRow family house: house occupies full plot width, neighboring buildings connected with fire walls – common urban form\\nSemi-detached house: one of two residential buildings connected by fire wall on one plot boundary\\nTownhouse: one dwelling in a row of buildings connected by party walls on at least one, maximum 2 plot boundaries", "hu": "Szabadon álló családiház: saját telken belül körül járható, oldalkert jellemzően min. 3,0 m\\nOldalhatáron álló családiház: egyik telekhatárra épült (vagy attól legfeljebb 1,0 m-re), egy homlokzata csak a szomszéd telkéről elérhető\\nZártsorú családiház: a ház a teljes telekszélességet elfoglalja, a szomszéd épületek tűzfalasan kapcsolódnak – belvárosban járatos beépítési forma\\nIkerház: egyik telekhatáron tűzfalasan összeérő lakóépületek egyike\\nSorház: telek legalább egy, legfeljebb 2 oldalhatárán egymáshoz határfalakkal csatlakozott épületsor egy lakása"}', NULL, NULL, NULL, false, 1, NULL, NULL, false, NULL, false, NULL, NULL),
